options.script:
var frame = data.series[0];

function getField(name) {
  var f = frame.fields.find(function(f){ return f.name === name; });
  if (!f) return [];
  var out = [];
  for (var i = 0; i < f.values.length; i++) out.push(f.values.get(i));
  return out;
}

var ra    = getField('ra');
var dec   = getField('dec');
var pmra  = getField('pmra');
var pmdec = getField('pmdec');

var pmMag = ra.map(function(_, i){
  return Math.sqrt(pmra[i]*pmra[i] + pmdec[i]*pmdec[i]);
});
var maxPm = Math.max.apply(null, pmMag) || 1;

var scale = 0.0008;
var tipX = ra.map(function(x, i){
  return x + pmra[i] * scale;
});
var tipY = dec.map(function(y, i){
  return y + pmdec[i] * scale;
});

var hover = ra.map(function(_, i){
  return ('RA: '    + ra[i].toFixed(4)    + '\u00b0' +
          '<br>Dec: '   + dec[i].toFixed(4)   + '\u00b0' +
          '<br>pmra: '  + pmra[i].toFixed(2)  + ' mas/yr' +
          '<br>pmdec: ' + pmdec[i].toFixed(2) + ' mas/yr' +
          '<br>|PM|: '  + pmMag[i].toFixed(1) + ' mas/yr');
});

// Shaft lines: base -> tip
var xShaft = [], yShaft = [];
ra.forEach(function(x, i){
  xShaft.push(x, tipX[i], null);
  yShaft.push(dec[i], tipY[i], null);
});

// V-shaped arrowheads drawn as line segments — no marker.angle or arrow symbol needed.
// Each head: arm1 -> tip -> arm2 -> null
var openAngle = Math.PI / 5; // 36 deg half-angle
var headFrac  = 0.15;        // arm length as fraction of shaft length
var xHead = [], yHead = [];
ra.forEach(function(x, i){
  var dx = tipX[i] - x;
  var dy = tipY[i] - dec[i];
  var shaftLen = Math.sqrt(dx*dx + dy*dy) || 1e-10;
  var theta    = Math.atan2(dy, dx);       // direction of motion
  var back     = theta + Math.PI;          // opposite direction
  var armLen   = shaftLen * headFrac;
  var x1 = tipX[i] + armLen * Math.cos(back + openAngle);
  var y1 = tipY[i] + armLen * Math.sin(back + openAngle);
  var x2 = tipX[i] + armLen * Math.cos(back - openAngle);
  var y2 = tipY[i] + armLen * Math.sin(back - openAngle);
  xHead.push(x1, tipX[i], x2, null);
  yHead.push(y1, tipY[i], y2, null);
});

// Base dots: coloured by PM magnitude, no border
var baseTrace = {
  type: 'scatter', mode: 'markers',
  x: ra, y: dec,
  marker: {
    size: 4,
    color: pmMag,
    colorscale: 'RdYlBu',
    reversescale: true,
    cmin: 0, cmax: maxPm,
    colorbar: { title: 'PM (mas/yr)', thickness: 14, len: 0.75 },
    line: { width: 0, color: 'rgba(0,0,0,0)' }
  },
  text: hover, hoverinfo: 'text', showlegend: false
};

var shaftTrace = {
  type: 'scatter', mode: 'lines',
  x: xShaft, y: yShaft,
  line: { color: 'rgba(147,197,253,0.65)', width: 1 },
  hoverinfo: 'none', showlegend: false
};

var headTrace = {
  type: 'scatter', mode: 'lines',
  x: xHead, y: yHead,
  line: { color: 'rgba(147,197,253,0.9)', width: 1.5 },
  hoverinfo: 'none', showlegend: false
};

// Sagittarius A* position marker
var sgrATrace = {
  type: 'scatter', mode: 'markers+text',
  x: [266.4168], y: [-29.0078],
  marker: {
    symbol: 'cross-thin',
    size: 20,
    color: '#facc15',
    line: { width: 2.5, color: '#facc15' }
  },
  text: ['Sgr A*'],
  textposition: 'top right',
  textfont: { color: '#facc15', size: 12 },
  hoverinfo: 'text',
  hovertext: ['Sagittarius A*<br>RA: 266.4168°<br>Dec: −29.0078°'],
  showlegend: false
};

return {
  data: [baseTrace, shaftTrace, headTrace, sgrATrace],
  layout: {
    xaxis: {
      title: 'Right Ascension (deg)',
      type: 'linear', autorange: 'reversed',
      color: '#d1d5db', gridcolor: '#374151', zerolinecolor: '#374151'
    },
    yaxis: {
      title: 'Declination (deg)',
      type: 'linear', scaleanchor: 'x', scaleratio: 1,
      color: '#d1d5db', gridcolor: '#374151', zerolinecolor: '#374151'
    },
    plot_bgcolor: '#111827',
    paper_bgcolor: '#111827',
    font: { color: '#d1d5db', size: 12 },
    margin: { t: 10, b: 50, l: 65, r: 20 }
  }
};

var frame = data.series[0];

function getField(name) {
  var f = frame.fields.find(function(f){ return f.name === name; });
  if (!f) return [];
  var out = [];
  for (var i = 0; i < f.values.length; i++) out.push(f.values.get(i));
  return out;
}

var ra   = getField('ra');
var dec  = getField('dec');
var bprp = getField('bp_rp');
var gmag = getField('phot_g_mean_mag');

var sizes = gmag.map(function(m) {
  return Math.max(2, Math.min(22, 19 - m));
});

var colorscale = [
  [0.000, '#9bb0ff'],
  [0.054, '#aabfff'],
  [0.135, '#cad7ff'],
  [0.216, '#f8f7ff'],
  [0.324, '#fff4ea'],
  [0.459, '#ffd2a1'],
  [0.595, '#ffb066'],
  [0.730, '#ff8833'],
  [0.865, '#ff4500'],
  [1.000, '#cc2200']
];

var hover = ra.map(function(_, i) {
  return ('RA: '      + ra[i].toFixed(4)   + '\u00b0' +
          '<br>Dec: ' + dec[i].toFixed(4)  + '\u00b0' +
          '<br>BP\u2212RP: ' + bprp[i].toFixed(2) +
          '<br>G: '   + gmag[i].toFixed(2) + ' mag');
});

return {
  data: [{
    type: 'scatter', mode: 'markers',
    x: ra, y: dec,
    marker: {
      size: sizes,
      color: bprp,
      colorscale: colorscale,
      cmin: -0.2, cmax: 3.5,
      colorbar: { title: 'BP\u2212RP', thickness: 14, len: 0.75 },
      line: { width: 0 },
      opacity: 0.95
    },
    text: hover, hoverinfo: 'text', showlegend: false
  }],
  layout: {
    xaxis: {
      title: 'Right Ascension (deg)',
      type: 'linear', autorange: 'reversed',
      color: '#d1d5db', gridcolor: '#1f2937', zerolinecolor: '#1f2937'
    },
    yaxis: {
      title: 'Declination (deg)',
      type: 'linear', scaleanchor: 'x', scaleratio: 1,
      color: '#d1d5db', gridcolor: '#1f2937', zerolinecolor: '#1f2937'
    },
    plot_bgcolor: '#000000',
    paper_bgcolor: '#111827',
    font: { color: '#d1d5db', size: 12 },
    margin: { t: 10, b: 50, l: 65, r: 20 }
  }
};
